records=[]
for i,(q,p) in enumerate(zip(Q,P),1):
    ans,der,checks=R[i];issues=[]
    if q['answer']!=ans:issues.append(f'候选答案{q["answer"]}与独立答案{ans}不同。')
    if q['parent_id']!=p['id'] or q['family_id']!=p['family_id']:issues.append('冻结父题或family不符。')
    if q['question']==p['question']:issues.append('题面未修改。')
    if q['input_modality']!='text' or q['image_assets']:issues.append('未满足纯文字输出。')
    if i==18 and q['difficulty']!='基础':issues.append('仅读取两y轴截距相减，实际基础，沿源中等标签需调整。')
    records.append({'id':q['id'],'independently_derived_answer':ans,'independent_derivation':der,'boundary_and_uniqueness_checks':checks,'status':'issue' if issues else 'pass','issues':issues,'content_sha256':hashlib.sha256(json.dumps({k:q[k] for k in ['question','options','answer','solution']},ensure_ascii=False,sort_keys=True,separators=(',',':')).encode('utf-8')).hexdigest()})
report={'reviewer_agent':'finish_variants_g9','reviewer_model':'inherited_parent_model','method':'先只读全70题面与四选项独立推导答案（未使用生成者solution/spec作为已知），再逐题对照候选答案、完整解析、冻结母题及实际改动/难度。只对最终文件绑定question/options/answer/solution SHA；008指代、034主推理、018难度问题已报生成者并重新复核；非教师批准。','count':70,'passed':sum(x['status']=='pass' for x in records),'issue_count':sum(x['status']=='issue' for x in records),'records':records}
(BASE/'review_g8.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({k:v for k,v in report.items() if k!='records'},ensure_ascii=False))
